hypridle_conf:
# =============================================================================
# Hypridle Configuration (~/.config/hypr/hypridle.conf)
# Ported from ~/.config/powerdevilrc & ~/.config/kscreenlockerrc
# =============================================================================

general {
    lock_cmd = pidof hyprlock || hyprlock
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch dpms on
}

# Dim display after 5 minutes (300s - matches Battery DimDisplayIdleTimeoutSec=300)
listener {
    timeout = 300
    on-timeout = brightnessctl -s set 10
    on-resume = brightnessctl -r
}

# Lock screen after 10 minutes (600s)
listener {
    timeout = 600
    on-timeout = loginctl lock-session
}

# Turn off display after 15 minutes (900s)
listener {
    timeout = 900
    on-timeout = hyprctl dispatch dpms off
    on-resume = hyprctl dispatch dpms on && brightnessctl -r
}
